CREATE TABLE workspaces (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
) STRICT;

CREATE TABLE tree_move_guards (
  id TEXT PRIMARY KEY,
  node_id TEXT NOT NULL,
  expected_tree_version INTEGER NOT NULL,
  created_at INTEGER NOT NULL
) STRICT;

CREATE TABLE revision_taxonomy_values (
  revision_id TEXT NOT NULL REFERENCES content_revisions(id) ON DELETE CASCADE,
  taxonomy_id TEXT NOT NULL REFERENCES taxonomies(id) ON DELETE CASCADE,
  term_ids_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(term_ids_json)),
  PRIMARY KEY(revision_id, taxonomy_id)
);

CREATE TRIGGER custom_contents_validate_insert
BEFORE INSERT ON custom_contents
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM content_items c JOIN custom_tables t ON t.id = NEW.table_id
    WHERE c.id = NEW.content_item_id AND c.content_type_key = 'custom-content'
      AND c.workspace_id = NEW.workspace_id AND c.site_id = NEW.site_id
      AND t.workspace_id = NEW.workspace_id AND t.table_kind = 'content' AND t.state = 'active'
  ) THEN RAISE(ABORT, 'CUSTOM_CONTENT_INVALID_BINDING') END;
END;

CREATE TRIGGER custom_table_fields_validate_insert
BEFORE INSERT ON custom_table_fields
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM custom_tables t JOIN custom_fields f ON f.id = NEW.field_id
    WHERE t.id = NEW.table_id AND t.workspace_id = f.workspace_id
  ) THEN RAISE(ABORT, 'CUSTOM_FIELD_WORKSPACE_MISMATCH') END;
END;

CREATE TRIGGER custom_entries_validate_insert
BEFORE INSERT ON custom_entries
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM custom_contents c WHERE c.id = NEW.custom_content_id AND c.table_id = NEW.table_id AND c.state = 'active'
  ) THEN RAISE(ABORT, 'CUSTOM_ENTRY_TABLE_MISMATCH') END;
  SELECT CASE WHEN NEW.parent_entry_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM custom_entries p JOIN custom_tables t ON t.id = NEW.table_id
    WHERE p.id = NEW.parent_entry_id AND p.table_id = NEW.table_id AND t.table_kind = 'master' AND t.hierarchical = 1
  ) THEN RAISE(ABORT, 'CUSTOM_ENTRY_PARENT_INVALID') END;
END;

CREATE TRIGGER custom_entry_revision_validate_insert
BEFORE INSERT ON custom_entry_revisions
WHEN EXISTS (SELECT 1 FROM custom_entries WHERE id = NEW.entry_id)
BEGIN
  SELECT CASE WHEN NEW.based_on_revision_id != (SELECT working_revision_id FROM custom_entries WHERE id = NEW.entry_id)
    THEN RAISE(ABORT, 'CUSTOM_ENTRY_REVISION_CONFLICT') END;
  SELECT CASE WHEN NEW.expected_lock_version != (SELECT lock_version FROM custom_entries WHERE id = NEW.entry_id)
    THEN RAISE(ABORT, 'CUSTOM_ENTRY_REVISION_CONFLICT') END;
  SELECT CASE WHEN NEW.revision_number != COALESCE((SELECT MAX(revision_number)+1 FROM custom_entry_revisions WHERE entry_id = NEW.entry_id),1)
    THEN RAISE(ABORT, 'CUSTOM_ENTRY_REVISION_NUMBER_INVALID') END;
END;

CREATE TRIGGER custom_entry_publish_validate
BEFORE UPDATE OF published_revision_id ON custom_entries
WHEN NEW.published_revision_id IS NOT NULL AND NEW.published_revision_id IS NOT OLD.published_revision_id
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM custom_entry_revisions r JOIN custom_entry_approvals a ON a.revision_id = r.id
    WHERE r.id = NEW.published_revision_id AND r.entry_id = NEW.id
      AND a.entry_id = NEW.id AND a.state = 'approved' AND a.revision_hash = r.content_hash
  ) THEN RAISE(ABORT, 'CUSTOM_ENTRY_APPROVAL_REQUIRED') END;
END;

CREATE TABLE mail_submission_payloads (
  submission_id TEXT PRIMARY KEY REFERENCES mail_submissions(id) ON DELETE CASCADE,
  values_json TEXT NOT NULL CHECK(json_valid(values_json)),
  created_at INTEGER NOT NULL
);

CREATE TRIGGER mail_forms_validate_insert
BEFORE INSERT ON mail_forms
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM content_items c JOIN custom_tables t ON t.id=NEW.table_id
    WHERE c.id=NEW.content_item_id AND c.content_type_key='mail-form'
      AND c.workspace_id=NEW.workspace_id AND c.site_id=NEW.site_id
      AND t.workspace_id=NEW.workspace_id AND t.table_kind='content' AND t.state='active'
  ) THEN RAISE(ABORT,'MAIL_FORM_INVALID_BINDING') END;
END;

CREATE TRIGGER mail_form_policy_validate_insert
BEFORE INSERT ON mail_form_field_policies
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM mail_forms m JOIN custom_table_fields tf ON tf.table_id=m.table_id
    WHERE m.id=NEW.mail_form_id AND tf.field_id=NEW.field_id
  ) THEN RAISE(ABORT,'MAIL_FORM_FIELD_NOT_IN_TABLE') END;
END;

CREATE TRIGGER mail_submission_validate_insert
BEFORE INSERT ON mail_submissions
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM mail_confirmation_sessions c
    WHERE c.id=NEW.confirmation_id AND c.mail_form_id=NEW.mail_form_id
      AND c.used_at IS NULL AND c.expires_at >= NEW.received_at
      AND c.schema_version=NEW.schema_version AND c.values_hash=NEW.payload_hash
  ) THEN RAISE(ABORT,'MAIL_CONFIRMATION_INVALID_OR_USED') END;
END;

CREATE TRIGGER mail_submission_mark_confirmation_used
AFTER INSERT ON mail_submissions
BEGIN
  UPDATE mail_confirmation_sessions SET used_at=NEW.received_at WHERE id=NEW.confirmation_id;
END;

CREATE TRIGGER validate_theme_release_artifacts
BEFORE INSERT ON theme_releases
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM design_token_revisions d
    WHERE d.id=NEW.design_token_revision_id AND d.theme_id=NEW.theme_id
  ) THEN RAISE(ABORT,'THEME_TOKEN_MISMATCH') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM layout_revisions l
    WHERE l.id=NEW.layout_revision_id AND l.theme_id=NEW.theme_id
  ) THEN RAISE(ABORT,'THEME_LAYOUT_MISMATCH') END;
END;

CREATE TRIGGER prevent_theme_release_mutation
BEFORE UPDATE ON theme_releases
BEGIN
  SELECT RAISE(ABORT,'THEME_RELEASE_IMMUTABLE');
END;

CREATE TRIGGER prevent_design_token_revision_mutation
BEFORE UPDATE ON design_token_revisions
BEGIN
  SELECT RAISE(ABORT,'DESIGN_TOKEN_REVISION_IMMUTABLE');
END;

CREATE TRIGGER prevent_layout_revision_mutation
BEFORE UPDATE ON layout_revisions
BEGIN
  SELECT RAISE(ABORT,'LAYOUT_REVISION_IMMUTABLE');
END;

CREATE UNIQUE INDEX uq_plugin_activation_scope
  ON plugin_activations(workspace_id, COALESCE(site_id, ''), plugin_id)
  WHERE state = 'active';

CREATE TRIGGER trg_plugin_release_immutable_update
BEFORE UPDATE ON plugin_releases
BEGIN
  SELECT RAISE(ABORT, 'PLUGIN_RELEASE_IMMUTABLE');
END;

CREATE TRIGGER trg_plugin_release_immutable_delete
BEFORE DELETE ON plugin_releases
BEGIN
  SELECT RAISE(ABORT, 'PLUGIN_RELEASE_IMMUTABLE');
END;

CREATE TRIGGER trg_plugin_activation_validate_insert
BEFORE INSERT ON plugin_activations
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM plugin_releases pr
    JOIN plugins p ON p.id = pr.plugin_id
    WHERE pr.id = NEW.plugin_release_id
      AND p.id = NEW.plugin_id
      AND p.workspace_id = NEW.workspace_id
      AND pr.state = 'ready'
      AND p.state = 'active'
  ) THEN RAISE(ABORT, 'PLUGIN_ACTIVATION_RELEASE_MISMATCH') END;
  SELECT CASE WHEN NEW.site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM sites s WHERE s.id = NEW.site_id AND s.workspace_id = NEW.workspace_id
  ) THEN RAISE(ABORT, 'PLUGIN_ACTIVATION_SITE_MISMATCH') END;
END;

CREATE TRIGGER trg_plugin_activation_no_reactivate
BEFORE UPDATE OF state ON plugin_activations
WHEN OLD.state = 'disabled' AND NEW.state = 'active'
BEGIN
  SELECT RAISE(ABORT, 'PLUGIN_ACTIVATION_REACTIVATION_FORBIDDEN');
END;

CREATE TABLE cf_oauth_login_challenges (
  state TEXT PRIMARY KEY,
  code_verifier TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL
) STRICT;
